// STEALTHPANDA: src/stealth/identity.zig
// Single source of truth for the browser identity stealthpanda claims.
// Everything that expresses "who am I" derives from HERE:
//   - navigator.userAgent            (Navigator.zig via HttpClient)
//   - navigator.userAgentData        (NavigatorUAData.zig)
//   - Sec-Ch-Ua / full-version-list  (Config.zig HttpHeaders -> HttpClient)
//   - CDP /json/version userAgent    (server/cdp/domains/browser.zig)
//
// DATA-DRIVEN: all values come from src/stealth/profile_data.zig, which is
// GENERATED by instruments/sp_profile_dump.py from a real Chrome build:
//
//     python3 ~/stealthpanda/instruments/sp_profile_dump.py \
//         --chrome <chrome-binary> --write && make build
//
// Never hardcode fingerprint values in this file — update the data, not the
// code (docs/stealthpanda/local/HOWTO-AGENTIC.md has the full loop).
//
// This file is new in the stealthpanda fork (AGPL-3.0); no bladebro code.

const std = @import("std");
const profile = @import("profile_data.zig");

pub const ua_full_version: []const u8 = profile.ua_full_version;
pub const ua_major: []const u8 = blk: {
    const s = profile.ua_full_version;
    break :blk s[0 .. std.mem.indexOfScalar(u8, s, '.') orelse s.len];
};

/// Exactly what the claimed Chrome sends on Linux x86_64.
pub const user_agent = profile.user_agent;

pub const js_platform = "Linux x86_64";
pub const ua_data_platform = "Linux";
pub const architecture = "x86";
pub const bitness = "64";
pub const model = "";
pub const mobile = false;
/// Observed: real Chrome 157 on desktop Linux answers "" here.
pub const platform_version = "";
pub const form_factors = [_][]const u8{"Desktop"};
pub const wow64 = false;

/// Brand table: navigator.userAgentData.brands uses `major`;
/// fullVersionList / uaFullVersion use `full`. Both derive from the dump.
pub const BrandEntry = struct {
    brand: [:0]const u8,
    major: [:0]const u8,
    full: [:0]const u8,
};

pub const brand_table = blk: {
    var arr: [profile.brands_major.len]BrandEntry = undefined;
    for (profile.brands_major, 0..) |b, i| {
        var full: [:0]const u8 = "";
        for (profile.brands_full_versions) |bf| {
            if (std.mem.eql(u8, bf[0], b.brand)) full = bf[1];
        }
        arr[i] = .{ .brand = b.brand, .major = b.major, .full = full };
    }
    break :blk arr;
};

/// `Sec-Ch-Ua` value: `"Chromium";v="157", "Not-A.Brand";v="99"`.
pub const sec_ch_ua: []const u8 = blk: {
    var out: []const u8 = "";
    for (brand_table, 0..) |b, i| {
        const sep: []const u8 = if (i == 0) "" else ", ";
        out = out ++ sep ++ "\"" ++ b.brand ++ "\";v=\"" ++ b.major ++ "\"";
    }
    break :blk out;
};

/// `Sec-Ch-Ua-Full-Version-List` value.
pub const sec_ch_ua_full_version_list: []const u8 = blk: {
    var out: []const u8 = "";
    for (brand_table, 0..) |b, i| {
        const sep: []const u8 = if (i == 0) "" else ", ";
        out = out ++ sep ++ "\"" ++ b.brand ++ "\";v=\"" ++ b.full ++ "\"";
    }
    break :blk out;
};

pub const sec_ch_ua_platform: []const u8 = "\"Linux\"";
pub const sec_ch_ua_mobile: []const u8 = "?0";

test "sec_ch_ua shape" {
    try std.testing.expect(std.mem.indexOf(u8, sec_ch_ua, "\";v=\"") != null);
    try std.testing.expectEqualStrings(profile.user_agent, user_agent);
}
